using UnityEngine;
namespace AbujaLife.World { public sealed class AbujaSeasonController:MonoBehaviour { public WeatherController weather; [Range(1,12)] public int month=10; [Range(0,1)] public float dailyRandom=.5f; public void RollWeather(){if(!weather)return;float r=Mathf.Repeat(dailyRandom+Random.value,1f);bool dry=month>=11||month<=3;if(dry)weather.SetWeather(r<.28f?WeatherController.Weather.Harmattan:WeatherController.Weather.Clear);else weather.SetWeather(r<.35f?WeatherController.Weather.Rain:r<.55f?WeatherController.Weather.Overcast:WeatherController.Weather.Clear);} } }
